parameters.inputSchema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "companies": {
      "type": "array",
      "description": "List of lead companies with verified intelligence and enriched contact data.",
      "items": {
        "type": "object",
        "properties": {
          "company_name": {
            "type": "string"
          },
          "website": {
            "type": "string",
            "format": "uri"
          },
          "tagline": {
            "type": "string"
          },
          "source": {
            "type": "string"
          },
          "batch_funding_stage": {
            "type": "string"
          },
          "team_size_estimate": {
            "type": "string"
          },
          "linkedin_page": {
            "type": "string",
            "format": "uri"
          },
          "content_gap_claimed": {
            "type": "string"
          },
          "content_gap_verified": {
            "type": "string",
            "enum": [
              "TRUE",
              "FALSE",
              "UNVERIFIED"
            ]
          },
          "verification_evidence": {
            "type": "string"
          },
          "personalized_pitch_angle": {
            "type": "string"
          },
          "outreach_priority_level": {
            "type": "string",
            "enum": [
              "HIGH",
              "MEDIUM",
              "LOW"
            ]
          },
          "apollo_organization_id": {
            "type": "string"
          },
          "hunter_domain_status": {
            "type": "string"
          }
        },
        "required": [
          "company_name",
          "website",
          "tagline",
          "source",
          "batch_funding_stage",
          "team_size_estimate",
          "linkedin_page",
          "content_gap_claimed",
          "content_gap_verified",
          "verification_evidence",
          "personalized_pitch_angle",
          "outreach_priority_level"
        ],
        "additionalProperties": false
      }
    }
  },
  "required": [
    "companies"
  ],
  "additionalProperties": false
}
